import numpy as np
lines = open('answer.xyz').read().splitlines()
n = int(lines[0])
els, coords = [], []
for l in lines[2:2+n]:
    p = l.split()
    els.append(p[0]); coords.append([float(x) for x in p[1:4]])
coords = np.array(coords)
# print all bonds within reasonable cutoffs
cov = {'H':0.31,'C':0.76,'F':0.57,'P':1.07,'Si':1.11,'Ni':1.24}
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(coords[i]-coords[j])
        if d < cov[els[i]]+cov[els[j]]+0.45:
            pass
# summarize Ni coordination
for i,el in enumerate(els):
    if el in ('Si','P'):
        print(i, el, round(np.linalg.norm(coords[i]-coords[0]),3))
# Si-F and P-C counts
import collections
nb = collections.defaultdict(list)
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(coords[i]-coords[j])
        if d < cov[els[i]]+cov[els[j]]+0.4:
            nb[i].append(j); nb[j].append(i)
for i in range(n):
    if els[i] in ('Ni','Si','P'):
        print(i, els[i], '->', [(j,els[j]) for j in nb[i]])
